css:
* { box-sizing: border-box; }
:root {
  --bg: #fafbfc; --panel: #fff; --border: #e1e4e8; --border-strong: #d0d7de;
  --text: #1f2328; --muted: #6e7781; --accent: #6f42c1; --accent-bg: #f5f0ff;
  --row-hover: #f6f8fa; --row-active: #ede7f8;
  --ok: #1a7f37; --err: #cf222e; --warn: #9a6700;
  --badge-bg: #eaeef2; --badge-text: #424a53;
  --json-key: #953800; --json-string: #0a3069; --json-number: #0550ae;
  --json-bool: #8250df; --json-null: #6e7781;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0d1117; --panel: #161b22; --border: #30363d; --border-strong: #3d444d;
    --text: #e6edf3; --muted: #8b949e; --accent: #d2a8ff; --accent-bg: #2d1b4f44;
    --row-hover: #1c2128; --row-active: #2d1b4f88;
    --ok: #3fb950; --err: #f85149; --warn: #d29922;
    --badge-bg: #21262d; --badge-text: #8d96a0;
    --json-key: #ffa657; --json-string: #a5d6ff; --json-number: #79c0ff;
    --json-bool: #d2a8ff; --json-null: #8b949e;
  }
}
html, body { height: 100%; }
body {
  font: 13px/1.5 -apple-system, "PingFang SC", system-ui, sans-serif;
  margin: 0; background: var(--bg); color: var(--text);
  display: flex; flex-direction: column; height: 100vh; overflow: hidden;
}
.topbar {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 16px; background: var(--panel);
  border-bottom: 1px solid var(--border); flex-shrink: 0;
}
.topbar-icon { color: var(--accent); font-weight: 700; font-size: 16px; }
.topbar-title { font-weight: 600; font-size: 14px; }
.topbar-id {
  color: var(--muted); font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px; cursor: pointer; padding: 2px 6px; border-radius: 4px;
}
.topbar-id:hover { background: var(--row-hover); }
.topbar-meta { margin-left: auto; color: var(--muted); font-size: 12px; display: flex; gap: 16px; }
.topbar-meta b { color: var(--text); }

.main { display: grid; grid-template-columns: 380px 1fr; flex: 1; overflow: hidden; }

.tree-pane { background: var(--panel); border-right: 1px solid var(--border); display: flex; flex-direction: column; overflow: hidden; }
.tree-search { padding: 8px 12px; border-bottom: 1px solid var(--border); flex-shrink: 0; }
.tree-search input {
  width: 100%; padding: 6px 10px 6px 28px;
  border: 1px solid var(--border-strong); border-radius: 6px;
  background: var(--bg); color: var(--text); font: inherit;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='14' height='14' viewBox='0 0 24 24' fill='none' stroke='%236e7781' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='11' cy='11' r='8'/><path d='m21 21-4.35-4.35'/></svg>");
  background-repeat: no-repeat; background-position: 8px center;
}
.tree-search input:focus { outline: none; border-color: var(--accent); }
.tree-toolbar { padding: 6px 12px; border-bottom: 1px solid var(--border); display: flex; gap: 8px; font-size: 11px; color: var(--muted); flex-shrink: 0; }
.tree-toolbar button { background: none; border: none; color: var(--muted); cursor: pointer; padding: 2px 4px; font: inherit; }
.tree-toolbar button:hover { color: var(--text); }
.tree-list { flex: 1; overflow-y: auto; padding: 4px 0 12px; }
.node-row {
  display: flex; align-items: center; padding: 4px 8px 4px 0;
  cursor: pointer; border-left: 2px solid transparent; user-select: none;
  font-size: 12.5px; white-space: nowrap;
}
.node-row:hover { background: var(--row-hover); }
.node-row.active { background: var(--row-active); border-left-color: var(--accent); }
.node-toggle { width: 16px; flex-shrink: 0; text-align: center; color: var(--muted); font-size: 9px; transition: transform 0.1s; }
.node-row.collapsed .node-toggle { transform: rotate(-90deg); }
.node-row.leaf .node-toggle { visibility: hidden; }
.node-icon { width: 18px; flex-shrink: 0; text-align: center; }
.node-name { flex: 1; overflow: hidden; text-overflow: ellipsis; margin-right: 6px; }
.node-row.status-error .node-name { color: var(--err); }
.node-row.status-aborted .node-name { color: var(--warn); }
.node-duration { color: var(--muted); font-size: 11px; font-family: ui-monospace, Menlo, monospace; flex-shrink: 0; }
.node-tokens { color: var(--muted); font-size: 11px; font-family: ui-monospace, Menlo, monospace; flex-shrink: 0; margin-right: 8px; opacity: 0.85; }
.node-children.hidden { display: none; }

.dag-pane { border-top: 1px solid var(--border); padding: 10px 12px; flex-shrink: 0; background: var(--panel); max-height: 240px; overflow-y: auto; }
.dag-title { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 6px; }
.dag-grid { display: flex; flex-wrap: wrap; gap: 6px; }
.dag-node { border: 1px solid var(--border-strong); background: var(--bg); padding: 4px 10px; border-radius: 14px; font-size: 11px; display: flex; gap: 6px; align-items: center; }
.dag-node.has-err { border-color: var(--err); background: rgba(207,34,46,0.06); }
.dag-node.has-abort { border-color: var(--warn); background: rgba(154,103,0,0.06); }
.dag-node code { background: none; padding: 0; font-size: inherit; color: inherit; }
.dag-node-count { color: var(--muted); font-family: ui-monospace, Menlo, monospace; }
.dag-node.has-err .dag-node-count { color: var(--err); }
.dag-node.has-abort .dag-node-count { color: var(--warn); }

.detail-pane { display: flex; flex-direction: column; overflow: hidden; background: var(--panel); }
.detail-empty { flex: 1; display: flex; align-items: center; justify-content: center; color: var(--muted); font-size: 14px; }
.detail-header { padding: 12px 20px; border-bottom: 1px solid var(--border); flex-shrink: 0; }
.detail-title { display: flex; align-items: baseline; gap: 10px; font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.detail-time { color: var(--muted); font-size: 12px; font-family: ui-monospace, Menlo, monospace; }
.badges { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 10px; }
.badge { display: inline-flex; align-items: center; gap: 4px; padding: 4px 10px; border-radius: 14px; background: var(--badge-bg); color: var(--badge-text); font-size: 11.5px; font-family: ui-monospace, Menlo, monospace; }
.badge.badge-model { background: var(--accent-bg); color: var(--accent); }
.badge.badge-error { background: rgba(207,34,46,0.12); color: var(--err); }
.badge-key { color: var(--muted); }

.detail-body { flex: 1; overflow-y: auto; padding: 16px 20px; }
.section { border-top: 1px solid var(--border); margin-top: 12px; padding-top: 12px; }
.section:first-child { border-top: none; margin-top: 0; padding-top: 0; }
.section-title { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 8px; display: flex; align-items: center; gap: 6px; }
.section-title .count { font-weight: 400; color: var(--muted); }
.jump-bar { display: flex; gap: 12px; font-size: 12px; margin-bottom: 12px; color: var(--muted); padding-bottom: 12px; border-bottom: 1px solid var(--border); }
.jump-bar a { color: var(--accent); text-decoration: none; cursor: pointer; }
.jump-bar a:hover { text-decoration: underline; }

.text-block { background: var(--bg); border: 1px solid var(--border); border-radius: 6px; padding: 10px 12px; white-space: pre-wrap; word-wrap: break-word; font-family: ui-monospace, Menlo, monospace; font-size: 12.5px; max-height: 600px; overflow-y: auto; }
.text-block.error { background: rgba(207,34,46,0.06); border-color: var(--err); color: var(--err); }
.text-block.warn { background: rgba(154,103,0,0.06); border-color: var(--warn); color: var(--warn); }
.thinking-block { background: rgba(111,66,193,0.04); border: 1px solid rgba(111,66,193,0.2); border-radius: 6px; padding: 10px 12px; white-space: pre-wrap; word-wrap: break-word; font-size: 12.5px; max-height: 400px; overflow-y: auto; color: var(--muted); font-style: italic; }

.json-tree { background: var(--bg); border: 1px solid var(--border); border-radius: 6px; padding: 10px 12px; font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 12px; max-height: 500px; overflow: auto; }
.json-row { padding: 1px 0; display: flex; align-items: flex-start; }
.json-line-num { width: 32px; text-align: right; color: var(--muted); opacity: 0.5; user-select: none; flex-shrink: 0; margin-right: 12px; font-size: 11px; }
.json-content { flex: 1; min-width: 0; }
.json-toggle { display: inline-block; width: 12px; text-align: center; cursor: pointer; color: var(--muted); user-select: none; }
.json-key { color: var(--json-key); }
.json-string { color: var(--json-string); }
.json-number { color: var(--json-number); }
.json-bool { color: var(--json-bool); }
.json-null { color: var(--json-null); font-style: italic; }
.json-bracket { color: var(--text); }
.json-meta { color: var(--muted); font-size: 11px; margin-left: 6px; }
.json-children.collapsed { display: none; }
.json-indent { display: inline-block; width: 14px; }
.json-string-content { white-space: pre-wrap; word-wrap: break-word; max-width: 100%; }

.tag { display: inline-block; padding: 1px 8px; border-radius: 10px; font-size: 10.5px; font-weight: 600; margin-left: 6px; text-transform: uppercase; letter-spacing: 0.04em; }
.tag-error { background: rgba(207,34,46,0.12); color: var(--err); }
.tag-warn { background: rgba(154,103,0,0.12); color: var(--warn); }
.tag-purple { background: var(--accent-bg); color: var(--accent); }

.tc-item { padding: 8px 10px; background: var(--bg); border: 1px solid var(--border); border-radius: 6px; margin-bottom: 6px; font-size: 12px; }
.tc-name { font-family: ui-monospace, Menlo, monospace; font-weight: 600; }
.tc-args { margin-top: 6px; background: var(--panel); padding: 6px 8px; border-radius: 4px; font-size: 11.5px; white-space: pre-wrap; word-wrap: break-word; max-height: 200px; overflow-y: auto; color: var(--muted); }
.fc-list { display: flex; flex-direction: column; gap: 4px; }
.fc-list code { background: var(--bg); padding: 2px 6px; border-radius: 3px; }
.skill-list { font-size: 12px; color: var(--muted); }
.skill-list code { color: var(--text); background: var(--bg); padding: 1px 5px; border-radius: 3px; }
.skill-list > div { margin: 2px 0; }
.no-data { color: var(--muted); font-size: 12px; font-style: italic; padding: 8px 0; }

